  let image = &quot;%2fPCUP%2fReligion-PNG%2fGozreh.png&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;#symbole1&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td id=&quot;symbole1&quot; style=&quot;text-align:center;&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux aux fid&#232;les de la divinit&#233; indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Gozreh (technique).ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/%2fPCUP%2fReligion-PNG%2fGozreh.png&quot; style=&quot;max-height:70px; max-width:70px&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br/&gt;commune chez&lt;br/&gt;les fid&#232;les&lt;br/&gt;de &lt;a class=&quot;pagelink&quot; href=&quot;Gozreh-(Technique).html&quot; title=&quot;Gozreh&quot;&gt;Gozreh&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Guide des z&#233;phyrs&lt;div style=&quot;float:right;&quot;&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Dieux de la mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Inner Sea Gods/Dieux de la mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoISG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;b&gt;Aura&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Transmutation.html&quot; title=&quot;Transmutation&quot;&gt;Transmutation&lt;/a&gt; mod&#233;r&#233;e ; &lt;b&gt;NLS&lt;/b&gt; 9 ; &lt;b&gt;Emplacement&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Objets-Merveilleux-Sans-Emplacement.html&quot; title=&quot;Objets merveilleux sans emplacement&quot;&gt;aucun&lt;/a&gt; ; &lt;b&gt;Prix&lt;/b&gt; 15 000 po ; &lt;b&gt;Poids&lt;/b&gt; 0,5 kg
&lt;div class=&quot;box&quot;&gt;Description&lt;/div&gt;
Des motifs verts et bleus tourbillonnants ornent la surface de ce &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guide-Magique.html&quot; title=&quot;Guide magique&quot;&gt;guide&lt;/a&gt;&lt;/i&gt; en ch&#234;ne fin, dont la boussole et l&#39;aiguille sont en acier l&#233;g&#232;rement poli et grav&#233; de th&#232;mes li&#233;s &#224; l&#39;aspect oc&#233;anique de &lt;a class=&quot;pagelink&quot; href=&quot;Gozreh-(Technique).html&quot; title=&quot;Gozreh&quot;&gt;Gozreh&lt;/a&gt;. L&#39;aiguille ne pointe pas vers le nord comme on pourrait s&#39;y attendre, mais indique plut&#244;t la direction du vent dans la zone entourant le guide. Un &lt;i&gt;guide des z&#233;phyrs&lt;/i&gt; conf&#232;re &#224; son porteur un bonus de circonstance de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Profession.html&quot; title=&quot;Profession&quot;&gt;Profession&lt;/a&gt; (marin). Une fois par jour, le porteur d&#39;un &lt;i&gt;guide des z&#233;phyrs&lt;/i&gt; peut d&#233;placer l&#39;aiguille pour changer la direction du vent vers n&#39;importe quelle direction sur la boussole. Autrement, le porteur peut augmenter ou diminuer l&#39;intensit&#233; du &lt;a class=&quot;pagelink&quot; href=&quot;Climat#Vents_4.html&quot; title=&quot;Les vents&quot;&gt;vent&lt;/a&gt; d&#39;une cat&#233;gorie tout en changeant sa direction. Un &lt;i&gt;guide des z&#233;phyrs&lt;/i&gt; n&#39;a aucun impact sur les effets de vent magiques, si ce n&#39;est celui d&#39;indiquer la direction dans laquelle ils se d&#233;placent.
&lt;div class=&quot;box&quot;&gt;Cr&#233;ation&lt;/div&gt;
&lt;b&gt;Conditions&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Dobjets-Merveilleux.html&quot; title=&quot;Cr&#233;ation d&amp;#39;objets merveilleux&quot;&gt;Cr&#233;ation d&#39;objets merveilleux&lt;/a&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contr&#244;le-Des-Vents.html&quot; title=&quot;Contr&#244;le des vents&quot;&gt;contr&#244;le des vents&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Modification-Des-Vents.html&quot; title=&quot;Modification des vents&quot;&gt;modification des vents&lt;/a&gt;&lt;/i&gt; ; &lt;b&gt;Co&#251;t&lt;/b&gt; 7 500 po
&lt;/div&gt;
